/* Hand-authored config.h for the vendored OpenAL Soft build (normally
   generated by meson/CMake from config.h.in). See
   //third_party/openal_soft:BUILD.openal.bazel.

   HRTF data is not embedded (ALSOFT_EMBED_HRTF_DATA left undefined) to avoid
   needing OpenAL Soft's hexify.py step; HRTF profiles can still be loaded
   from external files at runtime. Legacy EAX emulation is left disabled
   (ALSOFT_EAX 0) since this project doesn't use it. */
#define FORCE_ALIGN

/* #undef ALSOFT_EMBED_HRTF_DATA */
/* #undef HAVE_PROC_PIDPATH */

#if defined(_WIN32)
#define HAVE_GUIDDEF_H
#define HAVE_INTRIN_H
#define HAVE_CPUID_INTRINSIC 1
#else
#define HAVE_DLFCN_H
#define HAVE_CPUID_H
#define HAVE_GCC_GET_CPUID 1
#define HAVE_CPUID_INTRINSIC 0
#endif

/* #undef HAVE_PTHREAD_NP_H */
/* #undef HAVE_PTHREAD_SETSCHEDPARAM */
/* #undef HAVE_PTHREAD_SETNAME_NP */
/* #undef HAVE_PTHREAD_SET_NAME_NP */

#define ALSOFT_INSTALL_DATADIR "."

#define HAVE_RTKIT 0
#define ALSOFT_UWP 0
#define ALSOFT_EAX 0
